from __future__ import annotations

from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from pathlib import Path
from collections.abc import Iterable


GENERATED_FILE_WARNING = (
    "// This file is autogenerated. Do not edit by hand.\n"
    "// Edit Codegen/manifest.py and regenerate it instead."
)


def comma_separated(values: Iterable[str]) -> str:
    return ", ".join(values)


@dataclass(frozen=True)
class RenderContext:
    indent_level: int = 0
    indent_text: str = "    "

    def indent(self) -> RenderContext:
        return RenderContext(self.indent_level + 1, self.indent_text)

    def apply_indent(self, text: str) -> str:
        prefix = self.indent_text * self.indent_level
        return "\n".join(f"{prefix}{line}" if line else "" for line in text.splitlines())


class Node(ABC):
    @abstractmethod
    def render(self, context: RenderContext) -> str:
        raise NotImplementedError


@dataclass(frozen=True)
class Raw(Node):
    text: str

    def render(self, context: RenderContext) -> str:
        return context.apply_indent(self.text)


@dataclass(frozen=True)
class NewLines(Node):
    count: int

    def __post_init__(self) -> None:
        if self.count <= 0:
            raise ValueError("NewLines count must be positive")

    def render(self, context: RenderContext) -> str:
        return "\n" * self.count


def render_node_sequence(
    nodes: Iterable[Node], context: RenderContext, default_newlines: int
) -> str:
    output = ""
    for node in nodes:
        if isinstance(node, NewLines):
            output = output.rstrip("\n") + node.render(context)
            continue
        if output and not output.endswith("\n"):
            output += "\n" * default_newlines
        output += node.render(context)
    return output


@dataclass(frozen=True)
class Include(Node):
    path: str
    system: bool = True

    def render(self, context: RenderContext) -> str:
        left, right = ("<", ">") if self.system else ('"', '"')
        return context.apply_indent(f"#include {left}{self.path}{right}")


@dataclass(frozen=True)
class ForwardDeclaration(Node):
    name: str
    kind: str = "struct"

    def render(self, context: RenderContext) -> str:
        return context.apply_indent(f"{self.kind} {self.name};")


@dataclass(frozen=True)
class UsingDeclaration(Node):
    name: str
    value_type: str

    def render(self, context: RenderContext) -> str:
        return context.apply_indent(f"using {self.name} = {self.value_type};")


@dataclass(frozen=True)
class Member(Node):
    type_name: str
    name: str

    def __post_init__(self) -> None:
        if not self.type_name.strip() or not self.name.strip():
            raise ValueError("Member type and name must not be empty")

    def render(self, context: RenderContext) -> str:
        return context.apply_indent(f"{self.type_name} {self.name};")


@dataclass(frozen=True)
class FunctionDeclaration(Node):
    function: MemberFunctionSpec | FreeFunctionSpec

    def render(self, context: RenderContext) -> str:
        declaration = self.function.declaration_signature().rstrip(";") + ";"
        return context.apply_indent(declaration)


@dataclass(frozen=True)
class Function(Node):
    function: MemberFunctionSpec | FreeFunctionSpec
    owner_name: str | None = None
    is_header: bool = False

    def render(self, context: RenderContext) -> str:
        body = self.function.body.render(context.indent())
        return (
            f"{context.apply_indent(self.function.definition_signature(self.owner_name, self.is_header))} {{\n"
            f"{body}\n"
            f"{context.apply_indent('}')}"
        )


@dataclass
class FunctionParameter(Node):
    type_name: str
    name: str
    default_value: str | None = None

    def render(self, context: RenderContext) -> str:
        return context.apply_indent(self.declaration_text())

    def declaration_text(self) -> str:
        default_value = f" = {self.default_value}" if self.default_value else ""
        return f"{self.type_name} {self.name}{default_value}"

    def definition_text(self) -> str:
        return f"{self.type_name} {self.name}"


@dataclass(frozen=True)
class ParameterRef(Node):
    parameter: FunctionParameter

    @property
    def cpp_name(self) -> str:
        return self.parameter.name

    def render(self, context: RenderContext) -> str:
        return context.apply_indent(self.cpp_name)


class FunctionBody(Node, ABC):
    @property
    def function(self) -> MemberFunctionSpec | FreeFunctionSpec:
        function = getattr(self, "_function", None)
        if function is None:
            raise ValueError("Function body must be bound to a function before rendering")
        return function

    def bind(self, function: MemberFunctionSpec | FreeFunctionSpec) -> None:
        owner = getattr(self, "_function", None)
        if owner is not None and owner is not function:
            raise ValueError("Function body is already bound to a different function")
        object.__setattr__(self, "_function", function)


@dataclass(frozen=True)
class MemberFunctionSpec:
    name: str
    return_type: str
    parameters: tuple[FunctionParameter, ...]
    body: Node
    suffix: str = ""
    is_static: bool = False
    is_inline: bool = False
    template_parameters: str | None = None
    requires_clause: str | None = None

    def __init__(
        self,
        name: str,
        return_type: str,
        parameters: Iterable[FunctionParameter],
        body: Node,
        suffix: str = "",
        is_static: bool = False,
        is_inline: bool = False,
        template_parameters: str | None = None,
        requires_clause: str | None = None,
    ) -> None:
        object.__setattr__(self, "name", name)
        object.__setattr__(self, "return_type", return_type)
        object.__setattr__(self, "parameters", tuple(parameters))
        if not isinstance(body, Node):
            raise TypeError("Function bodies must be codegen nodes; use Raw for literal C++")
        object.__setattr__(self, "body", body)
        object.__setattr__(self, "suffix", suffix)
        object.__setattr__(self, "is_static", is_static)
        object.__setattr__(self, "is_inline", is_inline)
        object.__setattr__(self, "template_parameters", template_parameters)
        object.__setattr__(self, "requires_clause", requires_clause)
        if isinstance(self.body, FunctionBody):
            self.body.bind(self)

    def declaration_node(self) -> FunctionDeclaration:
        return FunctionDeclaration(self)

    def header_node(self) -> Node:
        if self.is_inline:
            return Function(self, is_header=True)
        return self.declaration_node()

    def definition_node(self, owner_name: str) -> Function:
        return Function(self, owner_name=owner_name)

    def parameter(self, parameter: FunctionParameter) -> ParameterRef:
        if not any(candidate is parameter for candidate in self.parameters):
            raise ValueError("Parameter does not belong to this function")
        return ParameterRef(parameter)

    def _parameters(self, include_defaults: bool) -> str:
        render = FunctionParameter.declaration_text if include_defaults else FunctionParameter.definition_text
        return comma_separated(render(parameter) for parameter in self.parameters)

    def declaration_signature(self) -> str:
        return self._signature(True)

    def definition_signature(self, owner_name: str | None, is_header: bool) -> str:
        return self._signature(is_header, owner_name)

    def _signature(self, include_defaults: bool, owner_name: str | None = None) -> str:
        static_prefix = "static " if self.is_static and owner_name is None else ""
        qualified_name = f"{owner_name}::{self.name}" if owner_name else self.name
        lines: list[str] = []
        if self.template_parameters:
            lines.append(f"template <{self.template_parameters}>")
        if self.requires_clause:
            lines.append(f"requires {self.requires_clause}")
        lines.append(
            f"{static_prefix}{self.return_type} {qualified_name}({self._parameters(include_defaults)})"
            f"{self.suffix}"
        )
        return "\n".join(lines)


@dataclass(frozen=True)
class FreeFunctionSpec:
    name: str
    return_type: str
    parameters: tuple[FunctionParameter, ...]
    body: Node
    suffix: str = ""
    is_inline: bool = False

    def __init__(
        self,
        name: str,
        return_type: str,
        parameters: Iterable[FunctionParameter],
        body: Node,
        suffix: str = "",
        is_inline: bool = False,
    ) -> None:
        object.__setattr__(self, "name", name)
        object.__setattr__(self, "return_type", return_type)
        object.__setattr__(self, "parameters", tuple(parameters))
        if not isinstance(body, Node):
            raise TypeError("Function bodies must be codegen nodes; use Raw for literal C++")
        object.__setattr__(self, "body", body)
        object.__setattr__(self, "suffix", suffix)
        object.__setattr__(self, "is_inline", is_inline)
        if isinstance(self.body, FunctionBody):
            self.body.bind(self)

    def declaration_node(self) -> FunctionDeclaration:
        return FunctionDeclaration(self)

    def header_node(self) -> Node:
        if self.is_inline:
            return Function(self, is_header=True)
        return self.declaration_node()

    def definition_node(self) -> Function:
        return Function(self)

    def parameter(self, parameter: FunctionParameter) -> ParameterRef:
        if not any(candidate is parameter for candidate in self.parameters):
            raise ValueError("Parameter does not belong to this function")
        return ParameterRef(parameter)

    def _parameters(self, include_defaults: bool) -> str:
        render = FunctionParameter.declaration_text if include_defaults else FunctionParameter.definition_text
        return comma_separated(render(parameter) for parameter in self.parameters)

    def declaration_signature(self) -> str:
        return self._signature(True, False)

    def definition_signature(self, owner_name: str | None, is_header: bool) -> str:
        if owner_name is not None:
            raise ValueError("Free function definitions must not have an owner name")
        return self._signature(is_header, is_header)

    def _signature(self, include_defaults: bool, include_inline: bool) -> str:
        inline_prefix = "inline " if include_inline and self.is_inline else ""
        return f"{inline_prefix}{self.return_type} {self.name}({self._parameters(include_defaults)}){self.suffix}"


@dataclass(frozen=True)
class Struct(Node):
    name: str
    nodes: tuple[Node, ...]
    bases: tuple[str, ...] = ()
    template: str | None = None
    export_specifier: str | None = None

    def __init__(
        self,
        name: str,
        nodes: Iterable[Node],
        bases: Iterable[str] = (),
        template: str | None = None,
        export_specifier: str | None = None,
    ) -> None:
        object.__setattr__(self, "name", name)
        object.__setattr__(self, "nodes", tuple(nodes))
        object.__setattr__(self, "bases", tuple(bases))
        object.__setattr__(self, "template", template)
        object.__setattr__(self, "export_specifier", export_specifier)
        member_names = [node.name for node in self.nodes if isinstance(node, Member)]
        duplicates = sorted({name for name in member_names if member_names.count(name) > 1})
        if duplicates:
            raise ValueError(f"Struct {self.name!r} has duplicate members: {', '.join(duplicates)}")

    def render(self, context: RenderContext) -> str:
        lines: list[str] = []
        if self.template:
            lines.append(context.apply_indent(f"template <{self.template}>"))
        inheritance = f" : {comma_separated(self.bases)}" if self.bases else ""
        export_specifier = f" {self.export_specifier}" if self.export_specifier else ""
        lines.append(context.apply_indent(f"struct{export_specifier} {self.name}{inheritance} {{"))
        lines.append(render_node_sequence(self.nodes, context.indent(), 2))
        lines.append(context.apply_indent("};"))
        return "\n".join(lines)


@dataclass(frozen=True)
class Namespace(Node):
    name: str
    nodes: tuple[Node, ...]

    def __init__(self, name: str, nodes: Iterable[Node]) -> None:
        object.__setattr__(self, "name", name)
        object.__setattr__(self, "nodes", tuple(nodes))

    def render(self, context: RenderContext) -> str:
        body = render_node_sequence(self.nodes, context, 2)
        return (
            f"{context.apply_indent(f'namespace {self.name} {{')}\n"
            f"{body}\n"
            f"{context.apply_indent(f'}} // namespace {self.name}')}"
        )


@dataclass(frozen=True)
class CppFile(Node):
    path: Path
    nodes: tuple[Node, ...] = field(default_factory=tuple)
    pragma_once: bool = True
    clang_format_off: bool = False
    prologue: tuple[str, ...] = field(default_factory=tuple)
    epilogue: tuple[str, ...] = field(default_factory=tuple)

    def __post_init__(self) -> None:
        object.__setattr__(self, "path", Path(self.path))
        object.__setattr__(self, "nodes", tuple(self.nodes))
        object.__setattr__(self, "prologue", tuple(self.prologue))
        object.__setattr__(self, "epilogue", tuple(self.epilogue))

    def render(self, context: RenderContext | None = None) -> str:
        if context is None:
            context = RenderContext()

        if context.indent_level != 0:
            raise ValueError("CppFile must be rendered at the root indentation level")

        sections: list[str] = [GENERATED_FILE_WARNING]
        sections.extend(self.prologue)
        if self.pragma_once:
            sections.append("#pragma once")
        if self.nodes:
            sections.append(render_node_sequence(self.nodes, context, 1))
        sections.extend(self.epilogue)
        rendered = "\n\n".join(sections).rstrip()
        if self.clang_format_off:
            return f"// clang-format off\n{rendered}\n// clang-format on\n"
        return rendered + "\n"


@dataclass(frozen=True)
class Module:
    name: str
    header: CppFile | None = None
    source: CppFile | None = None

    def files(self) -> tuple[CppFile, ...]:
        return tuple(file for file in (self.header, self.source) if file is not None)
